        self:transition("reconnecting", now, "Reconnect pressed; waiting for the new session")
    end
end
function Engine:step(s, now)
    if not self.active then return nil end
    local c = self.config
    if s.timer ~= nil and now >= (self.nextTimer or 0) then
        self.timer:observe(s.timer, now)
        self.nextTimer = now + 1.2
    end
    -- Disconnects have priority in every active state, including respawn and AFK.
    if now >= self.nextModal then
        self.nextModal = now + c.reconnectPoll
        self.modalFrames = s.reconnect and self.modalFrames + 1 or 0
        self.modalCandidate = s.reconnect == true
    end
    if self.modalCandidate then
        if self.modalFrames >= 2 and self.state ~= "reconnecting" then
            self.generation = self.generation + 1
            self.pending, self.fresh = nil, 0
            self.reconnectCount, self.nextReconnect = 0, now
            self:transition("reconnecting", now, "Reconnect button confirmed")
        end
        if self.modalFrames >= 2 and not self.pending and c.autoReconnect and not c.dryRun then
            if now >= (self.nextReconnect or 0) then
                if self.reconnectCount >= c.reconnectAttempts then
                    self:halt(now, "Reconnect retry limit reached; check Roblox")
                else return self:action("reconnect", now) end
            end
        end
        return nil
    end
    if self.pending then return nil end
    if self.state == "reconnecting" then
        if now - self.since > c.loadTimeout then
            self:halt(now, "Reconnect loading timed out")
        elseif s.start then
            self.startCount, self.requiresStart, self.fresh = 0, true, 0
            self.nextStart = now + c.loadWait
            self:transition("loading", now, "Hub returned; allowing the character to load")
        end
        return nil
    end
    if self.state == "loading" and now - self.since > c.loadTimeout then
        self:halt(now, "The hub did not become ready")
        return nil
    end
    if self.state == "afk" then return nil end
    local remaining = self.timer:remaining(now)
    if remaining and remaining <= c.afkMinutes * 60 and c.afkMinutes > 0 then
        self:transition("afk", now, "HTC threshold reached; waiting for the Reconnect button")
        return nil
    end
    if self.state == "respawn_menu" then
        if s.respawn and not c.dryRun then return self:action("respawn", now) end
        if now - self.since > 4 then self:halt(now, "Respawn entry was not recognized; Chamber paused") end
        return nil
    elseif self.state == "respawn_confirm" then
        if s.confirm and not c.dryRun then return self:action("confirm", now) end
        if now - self.since > 4 then self:halt(now, "Respawn confirmation was not found") end
        return nil
    elseif self.state == "respawning" then
        if now - self.since > c.respawnTimeout then
            self:halt(now, "Respawn loading timed out")
        elseif now >= self.readyAfter and s.alive and s.start and not s.confirm then
            self.fresh = self.fresh + 1
            if self.fresh >= 3 then
                self.startCount, self.nextStart, self.fresh = 0, now, 0
                self:transition("seeking", now, "Respawn finished; starting training again")
            end
        else self.fresh = 0 end
        return nil
    end
    -- Start is authoritative even when scenery or old targets resemble training.
    if s.start then
        self.fresh, self.mayAdopt = 0, false
        if c.autoStart and not c.dryRun and now >= (self.nextStart or 0) then
            if self.startCount >= c.startAttempts then
                self:halt(now, "Start retry limit reached; check the game screen")
            else return self:action("start", now) end
        end
        return nil
    end
    -- A fresh toggle can join an existing minigame. Recovery/reconnect still
    -- require a new Start; stationary hit rings alone cannot authorize adoption.
    local adopt = self.mayAdopt and self.state == "seeking" and s.alive and #(s.notes or {}) > 0
    if s.training and (not self.requiresStart or adopt) then
        self.fresh = self.fresh + 1
        if self.fresh >= 3 then
            self.requiresStart, self.mayAdopt = false, false
            self.lastTraining = now
            if self.state ~= "training" then
                self.sessions = self.sessions + 1
                self.startCount, self.recoveryCount, self.reconnectCount = 0, 0, 0
                self:transition("training", now, "Training active — ki flowing")
            end
        end
    else self.fresh = 0 end
    if self.state == "training" and not s.training and now - (self.lastTraining or now) >= 2 then
        self:transition("lost", now, "Training UI disappeared; checking recovery")
    end
    local grace = self.state == "starting" and c.startGrace or 15
    local missing = self.state == "lost" and now - (self.lastTraining or now) >= c.lostSeconds
    local stalled = (self.state == "seeking" or self.state == "starting") and now - self.since >= grace
    if (missing or stalled) and c.autoRecover and not c.dryRun then
        if not s.bindingsReady then
            self:halt(now, "Chamber prompts were not recognized automatically; game compatibility needs an update")
        elseif self.recoveryCount >= c.recoveryAttempts then
            self:halt(now, "Recovery retry limit reached")
        elseif s.menu then
            self.recoveryCount = self.recoveryCount + 1
            self.requiresStart = true
            return self:action("menu", now)
        else self:halt(now, "Lines menu was not recognized; Chamber paused") end
    end
    return nil
end
function Engine:canPlay(snapshot)
    return self.active and self.state == "training" and not self.pending and not self.modalCandidate
        and not snapshot.start and not self.config.dryRun
end
return Engine

end

__modules["src.Rhythm"] = function()
local require = __require
local Rhythm = {}
Rhythm.__index = Rhythm

function Rhythm.new(config, input)
    return setmetatable({config = config, input = input, tracks = {}, held = {},
        attempts = 0, bursts = 0, spam = nil, clear = 0, zero = 0}, Rhythm)
end
function Rhythm:release()
    local errors = {}
    for kind in pairs(self.held) do
        local ok, reason = pcall(self.input.up, self.input, kind)
        if not ok then errors[#errors + 1] = tostring(reason) else self.held[kind] = nil end
    end
    if #errors > 0 then error(table.concat(errors, "; ")) end
end
function Rhythm:reset()
    self:release()
    self.tracks, self.spam, self.done, self.clear, self.zero = {}, nil, nil, 0, 0
    self.releaseAt, self.nextPulse = nil, nil
end
function Rhythm:press(kinds, now, hold)
    for _, kind in ipairs(kinds) do
        self.held[kind] = true -- Retain for release even if a backend partially fails.
        self.input:down(kind)
        self.attempts = self.attempts + 1
    end
    self.releaseAt = now + hold / 1000
end
function Rhythm:step(notes, challenge, now)
    if self.releaseAt and now >= self.releaseAt then
        self:release()
        self.releaseAt = nil
        self.nextPulse = now + self.config.spamGapMs / 1000
    end
    local visible = challenge and challenge.visible and challenge.kind
    if self.done then
        self.clear = visible and 0 or self.clear + 1
        if self.clear >= 4 then self.done, self.clear = nil, 0 end
        return
    end
    if self.spam then
        self.clear = visible and 0 or self.clear + 1
        self.zero = visible and challenge.count == 0 and self.zero + 1 or 0
        if self.zero >= 3 or self.clear >= 4 then
            self:release()
            self.done, self.spam, self.releaseAt = self.zero >= 3, nil, nil
            self.clear, self.zero = 0, 0
            return
        end
        if not self.releaseAt and now >= (self.nextPulse or 0) and self.spam.count < self.config.spamMaxPresses then
            self:press({self.spam.kind}, now, self.config.spamHoldMs)
            self.spam.count = self.spam.count + 1
        end
        return
    end
    if visible and challenge.count == 0 then self.done = true; return end
    if visible then
        self:release()
        self.releaseAt, self.nextPulse = nil, now
        self.spam, self.tracks = {kind = challenge.kind, count = 0}, {}
        self.bursts = self.bursts + 1
        return self:step(notes, challenge, now)
    end
    local due, seen = {}, {}
    for _, n in ipairs(notes or {}) do
        seen[n.id] = true
        local t = self.tracks[n.id]
        if not t or n.x < t.x - 50 or n.kind ~= t.kind then
            t = {x = n.x, at = now, kind = n.kind, observed = 0, first = now}
            self.tracks[n.id] = t
        end
        local elapsed = now - t.at
        if elapsed > 0 then
            local speed = (n.x - t.x) / elapsed
            if speed > 60 and speed < 900 then t.speed = t.speed and t.speed * 0.3 + speed * 0.7 or speed end
            t.observed = t.observed + 1
        end
        t.x, t.at = n.x, now
        if t.speed and t.observed >= 2 and now - t.first >= 0.03 and not t.fired then
            local eta = ((n.target or 1025) - n.x) / t.speed + self.config.timingOffsetMs / 1000
            if eta <= 0 and eta > -0.15 and not self.releaseAt then
                due[n.kind], t.fired = true, true
            end
        end
    end
    for id, t in pairs(self.tracks) do if not seen[id] and now - t.at > 0.6 then self.tracks[id] = nil end end
    local kinds = {}
    for _, kind in ipairs({"left", "right", "q", "e"}) do if due[kind] then kinds[#kinds + 1] = kind end end
    if #kinds > 0 then self:press(kinds, now, self.config.holdMs) end
end
return Rhythm

end

__modules["src.GuiIndex"] = function()
local require = __require
-- Event-driven discovery. Neither bootstrap nor updates use GetDescendants.
local GuiIndex = {}
GuiIndex.__index = GuiIndex

function GuiIndex.new(ownGui, changed, removed, report)
    return setmetatable({ownGui = ownGui, changed = changed, removed = removed,
        report = report, records = {}, roots = {}, connections = {}, queue = {},
        queued = {}, head = 1, tail = 0, updates = {}, dirty = {}, updateHead = 1,
        updateTail = 0, maxUpdates = 32, maxWork = 96, budgetSeconds = 0.0008,
        processed = 0, lastWork = 0}, GuiIndex)
end
function GuiIndex:enqueue(object, root, expand)
    if self.ownGui and (object == self.ownGui or object:IsDescendantOf(self.ownGui)) then return end
    if not expand then
        if self.dirty[object] then return end
        local update = {object = object, root = root}
        self.updateTail = self.updateTail + 1
        self.updates[self.updateTail], self.dirty[object] = update, update
        return
    end
    local old = self.queued[object]
    if old then old.expand = old.expand or expand; return end
    local job = {object = object, root = root, expand = expand}
    self.tail = self.tail + 1
    self.queue[self.tail], self.queued[object] = job, job
end
function GuiIndex:remove(object)
    self.queued[object], self.dirty[object] = nil, nil
    local record = self.records[object]
    if record then
        for _, connection in ipairs(record.connections) do connection:Disconnect() end
        self.records[object] = nil
        self.removed(object)
    end
end
function GuiIndex:attach(name, root)
    self.roots[name] = root
    local ok, reason = pcall(function()
        self.connections[#self.connections + 1] = root.DescendantAdded:Connect(function(object)
            self:enqueue(object, name, false)
        end)
        self.connections[#self.connections + 1] = root.DescendantRemoving:Connect(function(object)
            self:remove(object)
        end)
    end)
    if not ok then self.report(name .. " cannot be observed: " .. tostring(reason)) end
    self:enqueue(root, name, true)
end
function GuiIndex:watch(object, record)
    local function changed() self:enqueue(object, record.root, false) end
    local function property(name)
        local ok, connection = pcall(function() return object:GetPropertyChangedSignal(name):Connect(changed) end)
        if ok then record.connections[#record.connections + 1] = connection end
    end
    property("Name")
    local class = object.ClassName
    if class == "TextLabel" or class == "TextButton" or class == "TextBox" then property("Text") end
    if class == "ImageLabel" or class == "ImageButton" then
        property("Image"); property("ImageRectOffset"); property("ImageRectSize")
    end
    local ok, connection = pcall(function() return object.AttributeChanged:Connect(changed) end)
    if ok then record.connections[#record.connections + 1] = connection end
end
function GuiIndex:visit(job)
    local object, root = job.object, self.roots[job.root]
    if not root or (object ~= root and not object:IsDescendantOf(root)) or object == self.ownGui then return false end
    local record = self.records[object]
    if not record and object:IsA("GuiObject") then
        record = {root = job.root, connections = {}}
        self.records[object] = record
        self:watch(object, record)
    end
    if record then self.changed(object, job.root) end
    return true
end
function GuiIndex:pump()
    local started, work = os.clock(), 0
    -- New prompts and changed counters must not wait behind a large inventory.
    -- Limit this queue as well so initial discovery can continue during updates.
    while self.updateHead <= self.updateTail and work < self.maxUpdates do
        if work > 0 and os.clock() - started >= self.budgetSeconds then break end
        local job = self.updates[self.updateHead]
        self.updates[self.updateHead], self.updateHead = nil, self.updateHead + 1
        work = work + 1
        if self.dirty[job.object] == job then
            self.dirty[job.object] = nil
            self:visit(job)
        end
    end
    if self.updateHead > self.updateTail then self.updates, self.updateHead, self.updateTail = {}, 1, 0 end
    while self.head <= self.tail and work < self.maxWork do
        if work > 0 and os.clock() - started >= self.budgetSeconds then break end
        local job = self.queue[self.head]
        work = work + 1
        if self.queued[job.object] ~= job then
            self.queue[self.head], self.head = nil, self.head + 1
        elseif job.children and job.cursor <= #job.children then
            self:enqueue(job.children[job.cursor], job.root, true)
            job.cursor = job.cursor + 1
        else
            if not job.visited then
                job.visited = true
                if self:visit(job) then
                    if job.expand then
                        local ok, children = pcall(job.object.GetChildren, job.object)
                        if ok then job.children, job.cursor = children, 1
                        else self.report(job.root .. " cannot be read by this executor") end
                    end
                end
            end
            if not job.children or job.cursor > #job.children then
                self.queue[self.head], self.queued[job.object] = nil, nil
                self.head = self.head + 1
            end
        end
    end
    if self.head > self.tail then self.queue, self.head, self.tail = {}, 1, 0 end
    self.lastWork, self.processed = work, self.processed + work
end
function GuiIndex:close()
    for _, connection in ipairs(self.connections) do connection:Disconnect() end
    for object in pairs(self.records) do self:remove(object) end
    self.roots, self.connections, self.queue, self.queued = {}, {}, {}, {}
    self.updates, self.dirty, self.updateHead, self.updateTail = {}, {}, 1, 0
    self.head, self.tail = 1, 0
end
return GuiIndex

end

__modules["src.Bindings"] = function()
local require = __require
local Timer = require("src.Timer")
local GuiIndex = require("src.GuiIndex")
local Bindings = {}
Bindings.__index = Bindings
local KINDS = {"left", "right", "q", "e"}
local ROLES = {"start", "menu", "respawn", "confirm", "reconnect", "timer", "targetTop", "targetBottom", "counterTop", "counterBottom"}
local ALIASES = {
    q = "q", e = "e", keyq = "q", keye = "e", qkey = "q", ekey = "e",
    lmb = "left", rmb = "right", mouse1 = "left", mouse2 = "right",
    mousebutton1 = "left", mousebutton2 = "right", leftclick = "left", rightclick = "right",
    leftmouse = "left", rightmouse = "right", leftmousebutton = "left", rightmousebutton = "right",
}
local INPUT_ATTRIBUTES = {"Key", "KeyCode", "Input", "InputType", "Action", "Button"}
local function clean(value)
    return tostring(value or ""):lower():gsub("<[^>]*>", ""):gsub("[^%w]", "")
end
local function alias(value)
    return ALIASES[clean(tostring(value or ""):match("([^%.]+)$"))]
end
local function textOf(object)
    local class = object.ClassName
    if class == "TextLabel" or class == "TextButton" or class == "TextBox" then return object.Text end
    return ""
end
local function visible(object, memo)
    if not object or not object.Parent or not object:IsA("GuiObject") then return false end
    if object.AbsoluteSize.X <= 0 or object.AbsoluteSize.Y <= 0 then return false end
    local chain, current, result = {}, object, true
    while current and current ~= game do
        if memo and memo[current] ~= nil then result = memo[current]; break end
        chain[#chain + 1] = current
        if current:IsA("GuiObject") and (not current.Visible or (current.ClassName == "CanvasGroup" and current.GroupTransparency >= 1)) then result = false; break end
        if current:IsA("LayerCollector") and not current.Enabled then result = false; break end
        current = current.Parent
    end
    if memo then for _, node in ipairs(chain) do memo[node] = result end end
    return result
end
local function buttonOf(object)
    local current = object
    while current and not current:IsA("LayerCollector") do
        if current:IsA("GuiButton") then return current end
        current = current.Parent
    end
end
local function imageOf(object)
    if object and (object.ClassName == "ImageLabel" or object.ClassName == "ImageButton") then
        return {image = object.Image, x = object.ImageRectOffset.X, y = object.ImageRectOffset.Y,
            w = object.ImageRectSize.X, h = object.ImageRectSize.Y}
    end
end
local function signature(image)
    if type(image) ~= "table" or not image.image or image.image == "" then return nil end
    return table.concat({image.image, image.x or 0, image.y or 0, image.w or 0, image.h or 0}, "|")
end
local function group() return {items = {}, positions = {}} end
local function insert(set, object)
    if set.positions[object] then return end
    set.items[#set.items + 1], set.positions[object] = object, #set.items + 1
end
local function remove(set, object)
    local position = set.positions[object]
    if not position then return end
    local last = set.items[#set.items]
    set.items[position], set.positions[last] = last, position
    set.items[#set.items], set.positions[object] = nil, nil
end

function Bindings.new(player, saved, ownGui)
    local self = setmetatable({player = player, saved = type(saved) == "table" and saved or {},
        ownGui = ownGui, roots = {}, errors = {}, reported = {}, lastKinds = {}, detectedKinds = {},
        records = {}, learned = {}, imageObjects = {}, controls = {}, nextRoots = 0,
        nextControls = 0, nextLegacy = 0, groups = {}, running = false, candidateReads = 0}, Bindings)
    for _, name in ipairs({"controls", "timers", "targets", "notes", "counters", "unknown"}) do self.groups[name] = group() end
    for _, kind in ipairs(KINDS) do
        local old = self.saved[kind]
        local key = type(old) == "table" and signature(old.signature)
        if key then self.learned[key] = kind end
    end
    self.index = GuiIndex.new(ownGui,
        function(object, root) self:classify(object, root) end,
        function(object) self:drop(object) end,
        function(reason)
            if not self.reported[reason] then self.reported[reason] = true; self.errors[#self.errors + 1] = reason end
        end)
    return self
end
function Bindings:drop(object)
    for _, set in pairs(self.groups) do remove(set, object) end
    local old = self.records[object]
    if old and old.image and self.imageObjects[old.image] then self.imageObjects[old.image][object] = nil end
    self.records[object] = nil
end
function Bindings:scale()
    local camera = workspace.CurrentCamera
    local size = camera and camera.ViewportSize or Vector2.new(1280, 720)
    return 1280 / math.max(1, size.X), 720 / math.max(1, size.Y)
end
function Bindings:point(object, sx, sy)
    local p, size = object.AbsolutePosition, object.AbsoluteSize
    return (p.X + size.X / 2) * sx, (p.Y + size.Y / 2) * sy, size.X * sx, size.Y * sy
end
function Bindings:kind(object)
    local explicit = alias(textOf(object)) or alias(object.Name)
    if not explicit then
        for _, name in ipairs(INPUT_ATTRIBUTES) do
            explicit = alias(object:GetAttribute(name))
            if explicit then break end
        end
    end
    if not explicit and object.Parent then explicit = alias(object.Parent.Name) end
    local text = clean(textOf(object))
    for _, kind in ipairs(KINDS) do
        local old = self.saved[kind]
        if type(old) == "table" and old.text and old.text ~= "" and old.text == text then explicit = explicit or kind end
    end
    local key = signature(imageOf(object))
    if explicit and key then
        local previous = self.learned[key]
        local learned = previous == nil and explicit or (previous == explicit and explicit or false)
        if previous ~= learned then
            self.learned[key] = learned
            for image in pairs(self.imageObjects[key] or {}) do
                if image ~= object then self.index:enqueue(image, "PlayerGui", false) end
            end
        end
    end
    return explicit or (key and self.learned[key]) or nil
end
function Bindings:classify(object, root)
    local previous = self.records[object]
    local controlsChanged = previous and (previous.role or previous.timer or previous.target)
    self:drop(object)
    local raw, name = textOf(object), clean(object.Name)
    local label, button = clean(raw), buttonOf(object)
    local r = {root = root, image = signature(imageOf(object))}
    self.records[object] = r
    if r.image then
        self.imageObjects[r.image] = self.imageObjects[r.image] or {}
        self.imageObjects[r.image][object] = true
    end
    if button then
        if label == "start" then r.role = "start"
        elseif label == "reconnect" then r.role = "reconnect"
        elseif label == "respawn" then r.role = "respawn"
        elseif root == "PlayerGui" and (label == "menu" or name == "menubutton" or name == "hamburgerbutton" or name == "linesmenu") then r.role = "menu" end
    end
    local sx, sy = self:scale()
    local x, y, w, h = self:point(object, sx, sy)
    if root == "PlayerGui" and button and not r.role and object.ClassName == "ImageButton"
        and math.abs(x - 63) < 22 and math.abs(y - 22) < 18 and w < 65 and h < 65 then r.role = "menu" end
    if r.role then r.button = button; insert(self.groups.controls, object) end
    if root ~= "PlayerGui" then
        if r.role or controlsChanged then self.nextControls = 0 end
        return
    end -- CoreGui is only needed for disconnect controls.
    r.timer = Timer.parse(raw)
    if r.timer then insert(self.groups.timers, object) end
    r.kind = self:kind(object)
    if r.kind then insert(self.groups.notes, object) end
    r.count = tonumber(raw:match("^%s*(%d+)%s*$"))
    if r.count and r.count <= 25 and ((x > 960 and x < 1085 and y > 495 and y < 655)
        or name:find("counter", 1, true) or name:find("countdown", 1, true)) then insert(self.groups.counters, object) end
    if math.abs(x - 1025) < 35 and w >= 45 and w <= 110 and h >= 45 and h <= 110 and math.abs(w - h) < 20 then
        if math.abs(y - 535) < 30 then r.target = "targetTop"
        elseif math.abs(y - 620) < 30 then r.target = "targetBottom" end
    end
    if r.target then insert(self.groups.targets, object) end
    if r.image and not r.kind and x > 280 and x < 1085 and y > 495 and y < 655 and w < 100 and h < 100 then
        insert(self.groups.unknown, object)
    end
    if r.role or r.timer or r.target or controlsChanged then self.nextControls = 0 end
end
function Bindings:resolve(binding)
    if type(binding) ~= "table" or type(binding.path) ~= "table" then return nil end
    local current = self.roots[binding.root]
    for _, name in ipairs(binding.path) do
        if not current or type(name) ~= "string" then return nil end
        local found
        for _, child in ipairs(current:GetChildren()) do
            if child.Name == name then
                if found then return nil end
                found = child
            end
        end
        current = found
    end
    return current
end
function Bindings:refresh(now)
    if now >= self.nextRoots then
        self.nextRoots = now + 2
        local roots = {PlayerGui = self.player:FindFirstChildOfClass("PlayerGui")}
        local ok, core = pcall(function() return game:GetService("CoreGui") end)
        if ok then roots.CoreGui = core end
        if roots.PlayerGui ~= self.roots.PlayerGui or roots.CoreGui ~= self.roots.CoreGui then
            self.index:close()
            self.roots, self.controls, self.nextControls, self.nextLegacy = roots, {}, 0, 0
            for _, name in ipairs({"PlayerGui", "CoreGui"}) do
                if roots[name] then self.index:attach(name, roots[name]) end
            end
        end
    end
    self.running = true
    self.index:pump()
end
function Bindings:pause()
    if not self.running then return end
    self.index:close()
    self.running, self.roots, self.controls, self.lastKinds, self.activeChallenge = false, {}, {}, {}, nil
    self.nextRoots, self.nextControls, self.nextLegacy = 0, 0, 0
end
function Bindings:each(name, callback, limit)
    local set = self.groups[name]
    for i = 1, math.min(#set.items, limit or 128) do
        local object = set.items[i]
        local record = self.records[object]
        self.candidateReads = self.candidateReads + 1
        if record then callback(object, record) end
    end
end
function Bindings:snapshot(now)
    self:refresh(now)
    local sx, sy = self:scale()
    local memo = {}
    if now >= self.nextControls then
        self.nextControls = now + 0.15
        local controls = {}
        self:each("controls", function(object, r)
            if visible(object, memo) and visible(r.button, memo) then
                local role = r.role
                local x = self:point(r.button, sx, sy)
                if role == "respawn" and x >= 300 then role = "confirm" end
                controls[role] = controls[role] or r.button
            end
        end)
        self:each("timers", function(object)
            local x, y = self:point(object, sx, sy)
            if x > 1120 and y > 650 and visible(object, memo) then controls.timer = object end
        end)
        self:each("targets", function(object, r)
            if visible(object, memo) then controls[r.target] = object end
        end)
        if now >= self.nextLegacy then
            self.nextLegacy, self.legacy = now + 1, {}
            for _, role in ipairs(ROLES) do self.legacy[role] = self:resolve(self.saved[role]) end
        end
        for role, object in pairs(self.legacy or {}) do if visible(object, memo) then controls[role] = object end end
        self.controls = controls
    end
    local controls = {}
    for role, object in pairs(self.controls) do if visible(object, memo) then controls[role] = object end end
    local notes, counters, nearest, filtered = {}, {}, {}, {}
    self:each("notes", function(object, r)
        if visible(object, memo) then
            local x, y = self:point(object, sx, sy)
            local lane = (r.kind == "left" or r.kind == "right") and "top" or "bottom"
            if x > 280 and x < 1085 and math.abs(y - (lane == "top" and 540 or 612)) < 30 then
                self.detectedKinds[r.kind] = true
                local target = controls[lane == "top" and "targetTop" or "targetBottom"]
                local targetX = target and self:point(target, sx, sy) or 1025
                notes[#notes + 1] = {id = object, kind = r.kind, x = x, target = targetX}
                if x <= targetX + 30 and (not nearest[lane] or x > nearest[lane].x) then nearest[lane] = {kind = r.kind, x = x} end
            end
        end
    end)
    self:each("counters", function(object, r)
        if visible(object, memo) then
            local x, y = self:point(object, sx, sy)
            if x > 960 and x < 1085 and y > 495 and y < 655 then counters[y < 575 and "top" or "bottom"] = r.count end
        end
    end)
    for _, lane in ipairs({"top", "bottom"}) do
        local counter = controls[lane == "top" and "counterTop" or "counterBottom"]
        if counter then
            local count = tonumber(textOf(counter):match("^%s*(%d+)%s*$"))
            if count and count <= 25 then counters[lane] = count end
        end
    end
    for lane, note in pairs(nearest) do
        local previous = self.lastKinds[lane]
        self.lastKinds[lane] = {kind = note.kind, at = now, votes = previous and previous.kind == note.kind and previous.votes + 1 or 1}
    end
    local challenge
    if self.activeChallenge then
        local count = counters[self.activeChallenge.lane]
        if count ~= nil then
            self.activeChallenge.missing = 0
            challenge = {visible = true, count = count, kind = self.activeChallenge.kind}
        else
            self.activeChallenge.missing = self.activeChallenge.missing + 1
            if self.activeChallenge.missing >= 4 then self.activeChallenge = nil end
        end
    end
    for _, lane in ipairs({"top", "bottom"}) do
        local count, previous = counters[lane], self.lastKinds[lane]
        if not self.activeChallenge and count ~= nil and previous and now - previous.at <= 6 and previous.votes >= 2 then
            challenge = {visible = true, count = count, kind = previous.kind}
            self.activeChallenge = {lane = lane, kind = previous.kind, missing = 0}
            break
        end
    end
    for _, note in ipairs(notes) do
        local duplicate = false
        for _, old in ipairs(filtered) do if old.kind == note.kind and math.abs(old.x - note.x) < 15 then duplicate = true; break end end
        if not duplicate then filtered[#filtered + 1] = note end
    end
    local character = self.player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    -- Recovery should not wait for the random sequence to show all four keys.
    -- Keep the guard for a HUD where no prompt has ever been understood.
    local ready = next(self.detectedKinds) ~= nil
    for _, kind in ipairs(KINDS) do
        if self.saved[kind] then ready = true end
    end
    return {start = controls.start ~= nil, menu = controls.menu ~= nil, respawn = controls.respawn ~= nil,
        confirm = controls.confirm ~= nil, reconnect = controls.reconnect ~= nil,
        timer = controls.timer and Timer.parse(textOf(controls.timer)),
        alive = humanoid ~= nil and humanoid.Health > 0, bindingsReady = ready,
        training = not controls.start and ((controls.targetTop and controls.targetBottom) ~= nil or #filtered > 0 or challenge ~= nil),
        notes = filtered, challenge = challenge, controls = controls}
end
Bindings.visible = visible
return Bindings

end

__modules["src.Input"] = function()
local require = __require
local Bindings = require("src.Bindings")
local Input = {}
Input.__index = Input
function Input.new(env)
    local ok, vim = pcall(function() return game:GetService("VirtualInputManager") end)
    local mouse = type(env.mouse1press) == "function" and type(env.mouse1release) == "function"
        and type(env.mouse2press) == "function" and type(env.mouse2release) == "function"
        and type(env.mousemoveabs) == "function"
    local keyboard = type(env.keypress) == "function" and type(env.keyrelease) == "function"
    return setmetatable({env = env, vim = ok and vim or nil, nativeMouse = mouse,
        nativeKeyboard = keyboard, held = {}, mouse = Vector2.new(0, 0)}, Input)
end
function Input:description()
    return (self.nativeMouse and "Executor mouse" or "VirtualInputManager mouse") .. " / "
        .. (self.nativeKeyboard and "executor keys" or "VirtualInputManager keys")
end
function Input:position()
    return game:GetService("UserInputService"):GetMouseLocation()
end
function Input:move(x, y)
    self.mouse = Vector2.new(x, y)
    if self.nativeMouse then self.env.mousemoveabs(x, y)
    elseif self.vim then self.vim:SendMouseMoveEvent(x, y, game)
    else error("Executor does not provide mouse movement") end
end
function Input:event(kind, down)
    if kind == "left" or kind == "right" then
        if self.nativeMouse then
            local fn = kind == "left" and (down and self.env.mouse1press or self.env.mouse1release)
                or (down and self.env.mouse2press or self.env.mouse2release)
            fn()
        elseif self.vim then
            local pos = self:position()
            self.vim:SendMouseButtonEvent(pos.X, pos.Y, kind == "left" and 0 or 1, down, game, 0)
        else error("Executor does not provide mouse input") end
    elseif kind == "q" or kind == "e" then
        if self.nativeKeyboard then
            (down and self.env.keypress or self.env.keyrelease)(kind == "q" and 0x51 or 0x45)
        elseif self.vim then self.vim:SendKeyEvent(down, kind == "q" and Enum.KeyCode.Q or Enum.KeyCode.E, false, game)
        else error("Executor does not provide key input") end
    else error("Unsupported input: " .. tostring(kind)) end
end
function Input:down(kind)
    self.held[kind] = true
    self:event(kind, true)
end
function Input:up(kind)
    self:event(kind, false)
    self.held[kind] = nil
end
function Input:releaseAll()
    local errors = {}
    for kind in pairs(self.held) do
        local ok, reason = pcall(self.up, self, kind)
        if not ok then errors[#errors + 1] = tostring(reason) end
    end
    if #errors > 0 then error(table.concat(errors, "; ")) end
end
local function waitUntil(duration, valid)
    local deadline = os.clock() + duration
    repeat
        if not valid() then error("Action cancelled") end
        task.wait()
    until os.clock() >= deadline
end
function Input:click(target, config, valid, park)
    if not Bindings.visible(target) then error("Target disappeared") end
    local validAction = valid
    valid = function() return validAction() and Bindings.visible(target) end
    local begin = self:position()
    local started, duration = os.clock(), config.approachMs / 1000
    repeat
        if not valid() or not target.Parent then error("Action cancelled") end
        local pos, size = target.AbsolutePosition, target.AbsoluteSize
        local goal = pos + size / 2
        -- AbsolutePosition is in the GUI's inset coordinate system.
        local root = target:FindFirstAncestorWhichIsA("ScreenGui")
        if root and not root.IgnoreGuiInset then goal = goal + game:GetService("GuiService"):GetGuiInset() end
        local t = math.min(1, (os.clock() - started) / duration)
        local smooth = t * t * (3 - 2 * t)
        local point = begin:Lerp(goal, smooth)
        self:move(math.floor(point.X + 0.5), math.floor(point.Y + 0.5))
        if t >= 1 then break end
        task.wait()
    until false
    waitUntil(config.hoverMs / 1000, valid)
    if not valid() then error("Target disappeared before the click") end
    valid = validAction -- A successful click may hide its target during the hold.
    local ok, reason = pcall(function()
        self:down("left")
        waitUntil(config.clickHoldMs / 1000, valid)
    end)
    local released, releaseReason = pcall(self.up, self, "left")
    if not released then error(releaseReason) end
    if not ok then error(reason) end
    if park then
        waitUntil(0.5, valid)
        local camera = workspace.CurrentCamera
        local size = camera and camera.ViewportSize or Vector2.new(1280, 720)
        local from = self:position()
        for step = 1, 30 do
            if not valid() then error("Action cancelled") end
            local point = from:Lerp(Vector2.new(size.X * 90 / 1280, size.Y * 435 / 720), step / 30)
            self:move(point.X, point.Y)
            task.wait(1 / 30)
        end
    end
end
return Input

end

__modules["src.UI"] = function()
local require = __require
local Timer = require("src.Timer")
local UI = {}
UI.__index = UI
local C = {
    bg = Color3.fromRGB(12, 14, 23), card = Color3.fromRGB(28, 32, 47),
    orange = Color3.fromRGB(255, 132, 35), gold = Color3.fromRGB(255, 211, 98),
    blue = Color3.fromRGB(94, 217, 255), text = Color3.fromRGB(242, 243, 249),
    muted = Color3.fromRGB(148, 157, 182), line = Color3.fromRGB(48, 53, 72),
}
local function new(class, parent, props)
    local object = Instance.new(class)
    for key, value in pairs(props or {}) do object[key] = value end
    object.Parent = parent
    return object
end
local function round(parent, radius)
    new("UICorner", parent, {CornerRadius = UDim.new(0, radius)})
end
local function label(parent, text, x, y, w, h, size, color, bold)
    return new("TextLabel", parent, {BackgroundTransparency = 1,
        Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(w, h),
        Text = text, TextColor3 = color, TextSize = size,
        Font = bold and Enum.Font.GothamBold or Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Center})
end
local function set(object, key, value)
    if object[key] ~= value then object[key] = value end
end
function UI.new(parent, onClose)
    local self = setmetatable({features = {}, order = {}, connections = {}, minimized = false}, UI)
    self.gui = new("ScreenGui", parent, {Name = "DBFR_SaiyanControl", ResetOnSpawn = false,
        IgnoreGuiInset = true, DisplayOrder = 10000, ZIndexBehavior = Enum.ZIndexBehavior.Sibling})
    self.window = new("Frame", self.gui, {Position = UDim2.fromOffset(22, 155),
        Size = UDim2.fromOffset(350, 80), BackgroundColor3 = C.bg, BorderSizePixel = 0})
    round(self.window, 14)
    new("UIStroke", self.window, {Color = C.orange, Transparency = 0.3, Thickness = 1})
    self.scale = new("UIScale", self.window, {Scale = 1})
    local header = new("Frame", self.window, {Size = UDim2.fromOffset(260, 65), BackgroundTransparency = 1, Active = true})
    local ball = new("Frame", header, {Position = UDim2.fromOffset(16, 16), Size = UDim2.fromOffset(34, 34),
        BackgroundColor3 = C.orange, BorderSizePixel = 0})
    round(ball, 34)
    new("UIGradient", ball, {Color = ColorSequence.new(C.gold, C.orange), Rotation = 65})
    label(ball, "★★★★", 2, 0, 30, 34, 9, Color3.fromRGB(165, 42, 23), true).TextXAlignment = Enum.TextXAlignment.Center
    label(header, "SAIYAN HUB", 62, 13, 195, 25, 19, C.text, true)
    label(header, "RIGHT SHIFT · SHOW / HIDE", 62, 38, 195, 15, 9, C.orange, true)
    local function windowButton(text, x, color)
        local button = new("TextButton", self.window, {Position = UDim2.fromOffset(x, 14),
            Size = UDim2.fromOffset(28, 28), BackgroundColor3 = C.card, BorderSizePixel = 0,
            Text = text, TextSize = 20, Font = Enum.Font.GothamBold, TextColor3 = color,
            AutoButtonColor = true})
        round(button, 7)
        return button
    end
    self.minimizeButton = windowButton("−", 273, C.gold)
    self.closeButton = windowButton("×", 307, C.orange)
    self.connections[#self.connections + 1] = self.minimizeButton.Activated:Connect(function()
        self:setMinimized(not self.minimized)
    end)
    self.connections[#self.connections + 1] = self.closeButton.Activated:Connect(onClose)
    local uis = game:GetService("UserInputService")
    self.connections[#self.connections + 1] = uis.InputBegan:Connect(function(input, processed)
        if processed or uis:GetFocusedTextBox() then return end
        if input.KeyCode == Enum.KeyCode.RightShift then
            self.window.Visible = not self.window.Visible
            if self.window.Visible then self:setMinimized(false) end
        end
    end)
    local dragging, origin, position
    self.connections[#self.connections + 1] = header.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging, origin, position = true, input.Position, self.window.Position
        end
    end)
    self.connections[#self.connections + 1] = uis.InputChanged:Connect(function(input)
        if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then
            local delta = input.Position - origin
            self.window.Position = UDim2.new(position.X.Scale, position.X.Offset + delta.X, position.Y.Scale, position.Y.Offset + delta.Y)
        end
    end)
    self.connections[#self.connections + 1] = uis.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then dragging = false end
    end)
    return self
end
function UI:setMinimized(minimized)
    self.minimized = minimized
    for _, feature in ipairs(self.order) do feature.row.Visible = not minimized end
    self.window.Size = UDim2.fromOffset(350, minimized and 65 or (76 + #self.order * 130))
    self.minimizeButton.Text = minimized and "+" or "−"
end
-- Each future feature gets one independent row and one toggle callback.
function UI:addFeature(id, title, onToggle)
    assert(not self.features[id], "Feature already registered: " .. id)
    local row = new("Frame", self.window, {Position = UDim2.fromOffset(14, 68 + #self.order * 130),
        Size = UDim2.fromOffset(322, 122), BackgroundTransparency = 1})
    local button = new("TextButton", row, {Position = UDim2.fromOffset(0, 0), Size = UDim2.fromOffset(322, 43),
        Text = title .. "  ·  OFF", TextSize = 13, Font = Enum.Font.GothamBold,
        TextColor3 = C.gold, BackgroundColor3 = C.card, BorderSizePixel = 0, AutoButtonColor = true})
    round(button, 9)
    local state = label(row, "OFF", 0, 50, 98, 18, 10, C.orange, true)
    local timer = label(row, "HTC  --:--:--", 106, 50, 216, 18, 11, C.blue, true)
    timer.TextXAlignment = Enum.TextXAlignment.Right
    local status = label(row, "Click to start Chamber automation.", 0, 73, 322, 42, 12, C.muted)
    status.TextWrapped = true
    local feature = {id = id, title = title, row = row, button = button, state = state, status = status, timer = timer}
    self.features[id], self.order[#self.order + 1] = feature, feature
    self.connections[#self.connections + 1] = button.Activated:Connect(onToggle)
    self:setMinimized(self.minimized)
    return feature
end
function UI:log(message) self.lastMessage = tostring(message) end
function UI:updateFeature(id, engine, rhythm, now)
    local feature = assert(self.features[id], "Unknown feature: " .. id)
    set(feature.button, "Text", feature.title .. (engine.active and "  ·  ON" or "  ·  OFF"))
    set(feature.button, "BackgroundColor3", engine.active and C.orange or C.card)
    set(feature.button, "TextColor3", engine.active and C.bg or C.gold)
    set(feature.state, "Text", engine.state:upper())
    set(feature.status, "Text", engine.status)
    set(feature.timer, "Text", "HTC  " .. Timer.format(engine.timer:remaining(now)))
    local camera = workspace.CurrentCamera
    if camera then
        set(self.scale, "Scale", math.max(0.5, math.min(1, (camera.ViewportSize.X - 30) / 350)))
    end
end
function UI:destroy()
    for _, connection in ipairs(self.connections) do connection:Disconnect() end
    self.gui:Destroy()
end
return UI

end

__modules["src.Main"] = function()
local require = __require
local Config = require("src.Config")
local Engine = require("src.Engine")
local Rhythm = require("src.Rhythm")
local Bindings = require("src.Bindings")
local Input = require("src.Input")
local UI = require("src.UI")
local Main = {}

function Main.start()
    local env = type(getgenv) == "function" and getgenv() or _G
    if env.__DBFR_APP then env.__DBFR_APP.unload() end
    local player = game:GetService("Players").LocalPlayer
    assert(player, "Run Chamber from the local Roblox client")
    local http = game:GetService("HttpService")
    local storage = "DBFR_Lua/settings.json"
    local saved = {}
    if type(env.readfile) == "function" then
        local ok, data = pcall(function() return http:JSONDecode(env.readfile(storage)) end)
        if ok and type(data) == "table" then saved = data end
    end
    local config = Config.new(type(saved.config) == "table" and saved.config or {})
    local ui, engine, bindings, rhythm
    local input = Input.new(env)
    local live, queueRegistered = true, false
    local actionRunning, nextEngine, nextUI, lastTick = false, 0, 0, -math.huge
    local wasPlaying = false
    local reportedBindingErrors = {}
    local connections = {}
    local function log(message)
        print("[Chamber Lua] " .. tostring(message))
        if ui then ui:log(message) end
    end
    local function save()
        if type(env.writefile) ~= "function" or type(env.makefolder) ~= "function" then return false end
        local ok, err = pcall(function()
            pcall(env.makefolder, "DBFR_Lua")
            env.writefile(storage, http:JSONEncode({version = 1, config = config, bindings = bindings.saved,
                resumeRequested = engine.active and config.resumeAfterTeleport}))
        end)
        if not ok then log("Settings could not be saved: " .. tostring(err)) end
        return ok
    end
    local function release()
        local ok, reason = pcall(rhythm.reset, rhythm)
        local released, detail = pcall(input.releaseAll, input)
        if not ok or not released then log("Input release needs attention: " .. tostring(reason or detail)) end
    end
    local function registerQueue()
        if not config.resumeAfterTeleport or queueRegistered then return end
        local queue = env.queue_on_teleport or env.queueonteleport
            or (type(env.syn) == "table" and env.syn.queue_on_teleport)
        if type(queue) ~= "function" then log("This executor has no teleport queue; reload after joining manually"); return end
        if type(env.readfile) ~= "function" then log("Teleport reload requires the loader and executor file storage"); return end
        local hasSource, source = pcall(env.readfile, "DBFR_Lua/chamber.lua")
        if not hasSource or type(source) ~= "string" or #source < 100 then
            log("Save the full loader.lua file as DBFR_Lua/chamber.lua in your executor workspace before enabling teleport reload")
            return
        end
        local ok, err = pcall(queue, [[
task.spawn(function()
    if not game:IsLoaded() then game.Loaded:Wait() end
    local env = type(getgenv) == "function" and getgenv() or _G
    local ok, saved = pcall(function()
        return game:GetService("HttpService"):JSONDecode(readfile("DBFR_Lua/settings.json"))
    end)
    if ok and saved.resumeRequested and saved.config and saved.config.resumeAfterTeleport then
        env.__DBFR_AUTORESUME = true
        local source = readfile("DBFR_Lua/chamber.lua")
        assert(loadstring(source, "DBFR Chamber"))()
    end
end)
]])
        if ok then queueRegistered = true; log("Teleport reload queued; executor must reattach to the next client")
        else log("Teleport queue failed: " .. tostring(err)) end
    end
    local function stop()
        engine:setActive(false, os.clock())
        release()
        bindings:pause()
        wasPlaying = false
        save()
        if live and ui then ui:updateFeature("chamber", engine, rhythm, os.clock()) end
    end
    local function toggle()
        if not live then return end
        if engine.active then stop()
        else
            release()
            bindings.lastKinds, bindings.activeChallenge = {}, nil
            engine:setActive(true, os.clock())
            save(); registerQueue()
            ui:updateFeature("chamber", engine, rhythm, os.clock())
        end
    end
    local function unload()
        if not live then return end
        stop(); live = false
        for _, connection in ipairs(connections) do connection:Disconnect() end
        if ui then ui:destroy() end
        env.__DBFR_APP = nil
        log("Unloaded")
    end
    engine = Engine.new(config, log)
    rhythm = Rhythm.new(config, input)
    local parent
    if type(env.gethui) == "function" then
        local ok, result = pcall(env.gethui)
        if ok then parent = result end
    end
    parent = parent or player:WaitForChild("PlayerGui")
    ui = UI.new(parent, unload)
    ui:addFeature("chamber", "CHAMBER AUTO TRAIN", toggle)
    bindings = Bindings.new(player, saved.bindings, ui.gui)
    env.__DBFR_APP = {unload = unload, toggle = toggle, version = "1.1.2", ui = ui, scanner = bindings}
    log("Chamber 1.1.2 loaded. Use the Chamber toggle to start or stop; Right Shift shows or hides the hub.")
    log(input:description())
    if type(env.writefile) ~= "function" then log("File storage unavailable: settings last for this session only") end
    ui:updateFeature("chamber", engine, rhythm, os.clock())
    local snapshot = {notes = {}, training = false}
    connections[#connections + 1] = game:GetService("RunService").Heartbeat:Connect(function()
        if not live or not engine.active then return end
        local now = os.clock()
        if now - lastTick < 1 / 60 - 0.001 then return end
        lastTick = now
        local ok, reason = pcall(function()
            snapshot = bindings:snapshot(now)
            for _, detail in ipairs(bindings.errors) do
                if not reportedBindingErrors[detail] then log(detail); reportedBindingErrors[detail] = true end
            end
            if now >= nextEngine then
                nextEngine = now + 0.1
                local wasActive = engine.active
                local previousState = engine.state
                local action = engine:step(snapshot, now)
                if previousState == "training" and engine.state ~= "training" then
                    bindings.lastKinds, bindings.activeChallenge = {}, nil
                end
                if wasActive and not engine.active then
                    release(); bindings:pause(); wasPlaying = false
                    save(); ui:updateFeature("chamber", engine, rhythm, now)
                end
                if action and not actionRunning then
                    actionRunning = true
                    release()
                    local target = snapshot.controls[action.kind]
                    task.spawn(function()
                        local succeeded, detail = pcall(input.click, input, target, config,
                            function() return live and engine.active and engine.generation == action.generation end,
                            action.kind == "start")
                        engine:complete(action, succeeded, os.clock(), detail)
                        actionRunning = false
                        if live then
                            if not engine.active then bindings:pause(); release(); wasPlaying = false end
                            save(); ui:updateFeature("chamber", engine, rhythm, os.clock())
                        end
                    end)
                elseif action then
                    -- A cancelled action may still be unwinding its release; retry only after it exits.
                    engine.pending = nil
                end
            end
            if engine:canPlay(snapshot) and not actionRunning then
                rhythm:step(snapshot.notes, snapshot.challenge, now)
                wasPlaying = true
            elseif wasPlaying and not actionRunning then
                rhythm:reset()
                wasPlaying = false
            end
            if now >= nextUI then
                nextUI = now + 0.4
                ui:updateFeature("chamber", engine, rhythm, now)
            end
        end)
        if not ok then
            engine:halt(now, "Stopped: " .. tostring(reason))
            release(); bindings:pause(); wasPlaying = false
            save(); ui:updateFeature("chamber", engine, rhythm, now)
        end
    end)
    if env.__DBFR_AUTORESUME then
        env.__DBFR_AUTORESUME = nil
        if config.resumeAfterTeleport then toggle() end
    end
    return env.__DBFR_APP
end
return Main

end

return __require('src.Main').start()
